#!/usr/bin/env python3
# Ús: python3 acords_a_live.py acords_csv.csv 138 2   (BPM, temps per compàs)
import csv, re, sys, html
src, bpm, bpb = sys.argv[1], float(sys.argv[2]), int(sys.argv[3])
offset = float(sys.argv[4]) if len(sys.argv) > 4 else 0.0   # segons on cau el compàs 1
step = 60.0 / bpm / 2            # graella = mig temps (corxera)
slots_bar = bpb * 2

def style(c):                     # Cmaj7->CMaj7, Am->A-, Em7->E-7
    c = re.sub(r'^([A-G][#b]?)maj', r'\1Maj', c)
    return re.sub(r'^([A-G][#b]?)m(?!aj|Aj)', r'\1-', c)

rows = [(float(t), c.strip()) for t, c in csv.reader(open(src))]
segs, last = [], -1
for t, c in rows:
    p = max(0, round((t - offset) / step))
    if c == 'N':
        end = p; continue
    if p <= last: p = last + 1     # evita col·lisions després d'arrodonir
    if segs and segs[-1][1] == style(c): continue
    segs.append((p, style(c))); last = p
end = max(end, segs[-1][0] + slots_bar)

def pos(p):                        # posició estil Live: compàs.temps.setzena
    return "%d.%d.%d" % (p // slots_bar + 1, (p % slots_bar) // 2 + 1, 1 + 2 * (p % 2))

with open('acords_locators.txt', 'w') as f:
    f.write("posició (compàs.temps.setzena)   acord   durada(temps)\n")
    for i, (p, c) in enumerate(segs):
        q = segs[i + 1][0] if i + 1 < len(segs) else end
        f.write("%-14s %-8s %g\n" % (pos(p), c, (q - p) / 2))

nb = (end + slots_bar - 1) // slots_bar
cells = []
for b in range(nb):
    lo, hi = b * slots_bar, (b + 1) * slots_bar
    items = []
    for i, (p, c) in enumerate(segs):
        q = segs[i + 1][0] if i + 1 < len(segs) else end
        if p < hi and q > lo:
            items.append('<span class="%s">%s</span>' % ('' if p >= lo else 'k', html.escape(c)))
    cells.append('<div class="b"><i>%d</i>%s</div>' % (b + 1, ' '.join(items)))
open('guia_acords.html', 'w').write("""<!doctype html><meta charset="utf-8"><title>Guia d'acords</title>
<style>body{font:20px system-ui;margin:20px;background:#fff;color:#111}
.g{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border-top:1px solid #999;border-left:1px solid #999}
.b{position:relative;min-height:56px;padding:22px 8px 6px;border-right:1px solid #999;border-bottom:1px solid #999;font-weight:600}
.b i{position:absolute;top:3px;left:6px;font:12px system-ui;color:#888}.b span{margin-right:10px}.k{color:#aaa;font-weight:400}
@media(prefers-color-scheme:dark){body{background:#111;color:#eee}}</style>
<h3>%d BPM · %d temps/compàs · gris = acord que ve del compàs anterior</h3><div class="g">%s</div>""" % (bpm, bpb, ''.join(cells)))
print(len(segs), "acords,", nb, "compassos")

#!/usr/bin/env python3
"""
als2rpp.py - Converteix les pistes d'un projecte d'Ableton Live 9 (.als)
en un projecte de Reaper (.rpp): noms, volum, pan, mute i clips d'audio
de l'arranjament (ITEM + SOURCE WAVE amb rutes absolutes).

Ús:
    python3 als2rpp.py projecte.als [sortida.rpp]

Només fa servir la biblioteca estàndard (Python 3.8 de l'Ubuntu 20.04 va bé).
"""
import gzip
import sys
import uuid
import xml.etree.ElementTree as ET
from pathlib import Path


def valor(node, ruta, per_defecte):
    """Retorna l'atribut Value del node trobat a 'ruta', o el valor per defecte."""
    if node is None:
        return per_defecte
    trobat = node.find(ruta)
    if trobat is None:
        return per_defecte
    return trobat.get("Value", per_defecte)


def nom_pista(pista):
    nom = valor(pista, "Name/EffectiveName", "")
    if not nom:
        nom = valor(pista, "Name/UserName", "")
    return nom or "Pista"


def guid():
    return "{" + str(uuid.uuid4()).upper() + "}"


def escapa(text):
    # Reaper no tolera cometes dobles dins del nom
    return text.replace('"', "'")


def llegeix_als(ruta):
    with gzip.open(ruta, "rb") as f:
        return ET.parse(f).getroot()


def ruta_mostra(file_ref, base_dir):
    """Resol la ruta absoluta del wav a partir de <FileRef> (relativa a la carpeta del .als)."""
    if file_ref is None:
        return None
    nom_node = file_ref.find("Name")
    if nom_node is None:
        return None
    nom = nom_node.get("Value", "")
    if not nom:
        return None
    rp = file_ref.find("RelativePath")
    parts = []
    if rp is not None:
        for e in list(rp):
            if e.tag == "RelativePathElement" and e.get("Dir"):
                parts.append(e.get("Dir"))
    candidata = Path(base_dir).joinpath(*parts, nom) if parts else Path(base_dir) / nom
    if candidata.exists():
        return str(candidata)
    # fallback: cerca pel nom dins la carpeta del projecte (per si la relativa canvia)
    trobats = list(Path(base_dir).rglob(nom))
    if trobats:
        return str(trobats[0])
    return str(candidata)


def clips_audio(pista):
    """Torna la llista d'<AudioClip>' d'arranjament ordenats per Time (beats)."""
    ev = pista.find("DeviceChain/MainSequencer/Sample/ArrangerAutomation/Events")
    if ev is None:
        return []
    clips = [c for c in ev.findall("AudioClip") if c.find("SampleRef/FileRef") is not None]
    def temps(c):
        try:
            return float(c.get("Time", "0"))
        except ValueError:
            return 0.0
    return sorted(clips, key=temps)


def main():
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)

    entrada = Path(sys.argv[1])
    sortida = Path(sys.argv[2]) if len(sys.argv) > 2 else entrada.with_suffix(".rpp")

    arrel = llegeix_als(entrada)
    liveset = arrel.find("LiveSet")
    if liveset is None:
        sys.exit("No s'ha trobat <LiveSet>: no sembla un .als vàlid.")

    tempo = valor(liveset, "MasterTrack/DeviceChain/Mixer/Tempo/Manual", "120")

    tipus = ("AudioTrack", "MidiTrack", "GroupTrack", "ReturnTrack")
    pistes = [p for p in liveset.find("Tracks") if p.tag in tipus]

    linies = ['<REAPER_PROJECT 0.1 "6.0" 0']
    try:
        tempo_f = float(tempo)
    except ValueError:
        tempo_f = 120.0
    linies.append("  TEMPO %.6f 4 4" % tempo_f)
    segons_per_batec = 60.0 / tempo_f if tempo_f else 0.5
    base_dir = entrada.parent

    total_items = 0
    for p in pistes:
        mixer = p.find("DeviceChain/Mixer")
        vol = float(valor(mixer, "Volume/Manual", "1"))   # lineal, 1.0 = 0 dB
        pan = float(valor(mixer, "Pan/Manual", "0"))      # -1 (esq) .. 1 (dreta)
        # A Live, Speaker=true vol dir que la pista està activa (no silenciada)
        muted = 0 if valor(mixer, "Speaker/Manual", "true").lower() == "true" else 1

        linies += [
            "  <TRACK " + guid(),
            '    NAME "%s"' % escapa(nom_pista(p)),
            "    VOLPAN %.8f %.6f -1 -1 1" % (vol, pan),
            "    MUTESOLO %d 0 0" % muted,
        ]
        for clip in clips_audio(p):
            try:
                pos_b = float(clip.get("Time", "0"))
                ini_b = float(valor(clip, "CurrentStart", clip.get("Time", "0")))
                fi_b = float(valor(clip, "CurrentEnd", clip.get("Time", "0")))
            except ValueError:
                continue
            dur_b = fi_b - ini_b
            if dur_b <= 0:
                continue
            pos_s = pos_b * segons_per_batec
            dur_s = dur_b * segons_per_batec
            wav = ruta_mostra(clip.find("SampleRef/FileRef"), base_dir)
            nom_wav = Path(wav).name if wav else escapa(valor(clip, "Name", "audio"))
            linies += [
                "    <ITEM",
                "      POSITION %.8f" % pos_s,
                "      LENGTH %.8f" % dur_s,
                "      SOFFS 0.00000000",
                '      NAME "%s"' % escapa(nom_wav),
                "      IGUID " + guid(),
                "      IID 1",
                "      <SOURCE WAVE",
                '        FILE "%s"' % (wav or ""),
                "      >",
                "    >",
            ]
            total_items += 1
        linies.append("  >")

    linies.append(">")
    sortida.write_text("\n".join(linies) + "\n", encoding="utf-8")
    print("Fet: %d pistes, %d clips audio -> %s" % (len(pistes), total_items, sortida))


if __name__ == "__main__":
    main()

