 };

 // DADES: viuen a dades_llm.js (edita ALLÀ; aquest fitxer només té lògica)
 const D = window.DADES_LLM;
 const data = D.models;
 const FABRI = D.fabri_prefix;
 const CAPS = D.caps_prefix;
 const WEB_SEARCH = new Set(D.web_search);
 const OFICIAL_MES = D.oficial_mes;
 const EXTRA_FREE = D.extra_free;
 const FORUM_US = D.forum_us;
 const CUTOFF = D.cutoff;
 const AGENTS_GO = D.agents_go || {};
 const ARENA = D.arena || {};
+const ARENA_CODE = D.arena_code || {};
+const AGENT_OK = D.agent_ok || {};
 const LIVE = D.livebench || {};
 const OLLB = D.ollb || {};
 const PC = D.pc || {};
 const EFFORT = D.effort || {};
 // --- TIPUS D'ESFORÇ (18-09): mapa explícit effort_tipus a dades_llm.js (no sniff de text) ---
 const EFFORT_TIPUS = (() => {
   const m = new Map();
   const T = D.effort_tipus || {};
   for (const n of (T.escala || [])) m.set(n, 'escala');
   for (const n of (T.onoff || [])) m.set(n, 'onoff');
   for (const n of (T.sd || [])) m.set(n, 'sd');
   return m;
 })();
 function effortTipus(name){
   if (EFFORT_TIPUS.has(name)) return EFFORT_TIPUS.get(name);
   const e = EFFORT[name];
   if (!e) return 'sd';
   const t = e.toLowerCase();
   if (/^s\/d/.test(t)) return 'sd';
   if (/low|max|xhigh|minimal/.test(t)) return 'escala';
