 // --- MITJANA 4F d'intel·ligència (17-09, pes igual, ESCALA AA): cada font es mapeja
 // al rang AA del set i es fa mitjana de les disponibles · ≈ si <4 fonts o AA provisional ---
 function minMax4(vals){ let mn=Infinity,mx=-Infinity; for(const v of vals){ if(v==null||isNaN(v))continue; if(v<mn)mn=v; if(v>mx)mx=v; } return [mn,mx]; }
 const [aaMn,aaMx] = minMax4(data.map(d=>d[3]));
 const [arMn,arMx] = minMax4(Object.values(ARENA).map(Number));
 const [liMn,liMx] = minMax4(Object.values(LIVE));
 const [olMn,olMx] = minMax4(Object.values(OLLB));
 const normAA = (v,mn,mx)=> (mx>mn) ? aaMn + (v-mn)/(mx-mn)*(aaMx-aaMn) : (aaMn+aaMx)/2;
 function mitjana4F(name, score, est){
   const parts = []; const det = {};
   if(score!=null){ parts.push(normAA(score,aaMn,aaMx)); det.aa = score; }
   if(ARENA[name]!=null && !isNaN(Number(ARENA[name]))){ parts.push(normAA(Number(ARENA[name]),arMn,arMx)); det.arena = Number(ARENA[name]); }
   if(LIVE[name]!=null){ parts.push(normAA(LIVE[name],liMn,liMx)); det.live = LIVE[name]; }
   if(OLLB[name]!=null){ parts.push(normAA(OLLB[name],olMn,olMx)); det.ollb = OLLB[name]; }
   if(!parts.length) return {mean:null, n:0, est:true, det};
   const mean = parts.reduce((a,b)=>a+b,0)/parts.length;
   return {mean, n:parts.length, est: !!est || parts.length<4, det};
 }
 const MITJ = new Map(data.map(d=>[d[0]+'|'+d[1], mitjana4F(d[0], d[3], d[4])]));
 function empresa(nom){
