 const US_OFI = D.us_ofi || {};
 const US_ALT = D.us_alt || {};
 const US_APROX = new Set(D.us_aprox || []);
 function us4F(name, via, cat, limit){
   if (cat === 'no') return {u:0, tag:'—', det:'sense accés'};
   if (cat === 'go' && OFICIAL_MES[name]){
     const ap = US_APROX.has(name + '|' + via);
     return {u:OFICIAL_MES[name], tag: ap ? 'OFI~' : 'OFI', det:'OFI docs Go' + (ap ? ' (xifra estimada)' : '')};
   }
   const key = name + '|' + via;
   if (US_OFI[key] !== undefined) return {u:US_OFI[key], tag:'OFI', det:'OFI proveïdor'};
   const A = US_ALT[key] || {};
   const vals = []; const det = [];
   if (A.pub != null){ vals.push(A.pub); det.push('PUB ' + A.pub.toLocaleString('ca-ES')); }
   if (FORUM_US[key] !== undefined){ vals.push(FORUM_US[key]); det.push('FOR ' + FORUM_US[key].toLocaleString('ca-ES')); }
   if (A.mes != null){ vals.push(A.mes); det.push('MES ' + A.mes.toLocaleString('ca-ES')); }
   if (A.pru != null){ vals.push(A.pru); det.push('PRU ' + A.pru.toLocaleString('ca-ES')); }
   if (vals.length){
     const mean = vals.reduce((a,b)=>a+b,0)/vals.length;
     return {u:mean, tag: vals.length + '/4', det: det.join(' + ')};
   }
   // fallback: mes explícit al triple com a PUB solitari (1/4); si no, s/d
   let m;
   if ((m = limit.match(/≈?([\d.,]+)\s*-\s*([\d.,]+)\s*(?:req|msg)\/mes/))) return {u:parseFloat(m[2].replace(/\./g,'').replace(/,/g,'')), tag:'1/4', det:'PUB text (rang→màxim)'};
   if ((m = limit.match(/([\d.,]+)\s*(?:req|msg)\/mes/))) return {u:parseFloat(m[1].replace(/\./g,'').replace(/,/g,'')), tag:'1/4', det:'PUB text'};
   if ((m = limit.match(/([\d.,]+)\s*req\/5h/))) return {u:parseFloat(m[1].replace(/\./g,''))*5, tag:'1/4', det:'PUB text (5h→mes)'};
   if ((m = limit.match(/([\d.,]+)\s*req\/dia/))) return {u:parseFloat(m[1].replace(/\./g,''))*30, tag:'1/4', det:'PUB text (dia→mes)'};
   if ((m = limit.match(/(\d+)\s*-\s*(\d+)\s*(?:msg\s*)?\/dia/))) return {u:Number(m[2])*30, tag:'1/4', det:'PUB text (rang dia→màxim)'};
   return {u:null, tag:'s/d', det:'sense fonts'};
 }
 const US4 = new Map(data.map(d => [d[0] + '|' + d[1], us4F(d[0], d[1], d[2], d[5])]));
 const US = new Map([...US4].map(([k,v]) => [k, v.u]));
 const USTAG = new Map([...US4].map(([k,v]) => [k, v.tag]));
 const USDET = new Map([...US4].map(([k,v]) => [k, v.det]));

 // ---------- ORDENACIONS ----------
 // Ordenació COMBINADA (08-09, petició de l'operador; 17-09 amb mitjana 4F; 18-09 escala ús sqrt): mitjana dels 2 eixos
 // amb LES MATEIXES escales que pinten les barres → el rànquing coincideix amb
 // el que es veu: intel·ligència = mitjana4F/100 · ús =
 // sqrt(us)/sqrt(226600) · ∞ compta com a 1 (màxim, com la barra).
 // s/d (null) i sense accés (us=0) → -1: queden al final (igual que a l'ordre per ús).
 function combVal(d){
   const [name, route] = d;
   const M = MITJ.get(name + '|' + route);
   const u = US.get(name + '|' + route);
   if (M.mean == null || u == null || u === 0 || u === undefined) return -1;
   const nI = M.mean / maxScore;
   const nU = Math.sqrt(u) / Math.sqrt(US_MAX);
   return (nI + nU) / 2;
 }
 const ORDRES = {
   intel: { cmp: (a,b) => ((MITJ.get(b[0]+'|'+b[1]).mean) ?? -1) - ((MITJ.get(a[0]+'|'+a[1]).mean) ?? -1),
            nota: "ordenat per MITJANA 4F d'intel·ligència (AA+Arena+LiveBench+BenchLM, desc) · la barra esquerra i el valor de sobre són la mitjana" },
   us:    { cmp: (a,b) => (US.get(b[0]+'|'+b[1]) ?? -1) - (US.get(a[0]+'|'+a[1]) ?? -1),
            nota: "ordenat per ÚS mensual (OFI si hi ha oficial · si no mitjana pub/for/mes/pru · ∞ tapat a 30.000 · s/d i sense accés al final) · la barra esquerra segueix sent la mitjana 4F" },
   combinat: { cmp: (a,b) => combVal(b) - combVal(a),
            nota: "ordenat per MITJANA COMBINADA dels 2 eixos: (mitjana4F/100 + ús sqrt/226600) ÷ 2 — guanya l'EQUILIBRAT, els monopous (molta nota i poca quota, o al revés) baixen · el valor de sobre segueix sent la mitjana 4F · s/d i sense accés al final" },
   arena: { cmp: (a,b) => ((ARENA[b[0]] != null ? Number(ARENA[b[0]]) : -1)) - ((ARENA[a[0]] != null ? Number(ARENA[a[0]]) : -1)),
            nota: "ordenat per ARENA (Elo text LMArena, vots humans — orientatiu, no comparable amb l'AA) · sense Elo al final" }
 };

 const maxScore = 62; // mitjana 4F en escala AA (17-09): el sostre és el màxim AA del set, com abans
 // Escala d'ÚS (18-09): arrel quadrada — punt mig entre log i lineal: les quotes petites
 // es veuen i les proporcions s'aprecien (810→6% · 3.000→11,5% · 226.600→100%).
 const US_MAX = 226600;
 const sqrtU = u => Math.min(100, Math.sqrt(u) / Math.sqrt(US_MAX) * 100);
 // Tics de referència 100·1K·10K·100K posicionats en la mateixa escala sqrt (2,1% · 6,6% · 21,0% · 66,4%)
 const TICS_US = [100, 1000, 10000, 100000].map(t =>
   '<div style="position:absolute;top:0;bottom:0;left:' + (Math.sqrt(t) / Math.sqrt(US_MAX) * 100).toFixed(1) + '%;width:1px;background:rgba(255,255,255,.38);pointer-events:none"></div>'
 ).join('');
 const rows = document.getElementById('rows');
 const axisEl = document.querySelector('.axis');
 const comptEl = document.getElementById('comptador');
 const selGo = document.getElementById('selGo');
 const selEffort = document.getElementById('selEffort');

 function renderRows(mode){
   const o = ORDRES[mode];
   const goSel = selGo.value;
   const capSel = selCaps.value;
   const effSel = selEffort.value;
   const llista = [...data]
     .filter(d => !goSel || d[2] === goSel)
     .filter(d => !capSel || capsVia(d[0], d[1]).includes(capSel))
     .filter(d => !effSel || effortTipus(d[0]) === effSel)
     .sort(o.cmp);
   rows.innerHTML = '';
   axisEl.textContent = 'Eix central (0 al mig) — ESQUERRA ◀: mitjana 4F amb valor a sobre (escala AA) · DRETA ▶: ús req/mes amb triple a sota (escala arrel quadrada amb tics 100·1K·10K·100K, 0-100%) · ≈ = <4 fonts o provisional · s/d = sense dades · ' + o.nota;
   comptEl.textContent = llista.length + ' / ' + data.length + ' models/vies'
     + (goSel ? ' · FILTRE: ' + ({free:'Zen Free sí', cbx:'Chatbox sí', api:'API sí', go:'Go sí'}[goSel] || goSel) : '')
     + (capSel ? ' · CAPACITAT: ' + (selCaps.options[selCaps.selectedIndex] ? selCaps.options[selCaps.selectedIndex].text : capSel) : '')
     + (effSel ? ' · ESFORÇ: ' + (selEffort.options[selEffort.selectedIndex] ? selEffort.options[selEffort.selectedIndex].text : effSel) : '')
     + ' · el límit de la via a la dreta';
   llista.forEach(([name,route,cat,score,est,limit]) => {
     const M = MITJ.get(name + '|' + route);
     const has = M.mean != null;
     const color = has ? COL[cat] : COL.na;
     const label = has ? (M.est ? '≈' : '') + M.mean.toFixed(1) + ' · ' + M.n + '/4' : 's/d';
     const det4F = has ? ('4F(' + M.n + '/4):'
       + (M.det.aa != null ? ' AA ' + M.det.aa : '')
       + (M.det.arena != null ? ' · Arena ' + M.det.arena : '')
       + (M.det.live != null ? ' · Live ' + M.det.live : '')
       + (M.det.ollb != null ? ' · BenchLM ' + M.det.ollb : '')) : 'sense fonts (s/d)';
     const row = document.createElement('div');
     row.className = 'fila';
     const ag = AGENTS_GO[name + '|' + route] || null;   // agent numerat (si la fila en té: 1-6 a Go, 7-8 a Free)
     row.dataset.nom = name;
     row.dataset.cat = cat;   // A: accent de targeta per categoria (només presentació)
     if (ag) row.dataset.agent = ag;   // cercable: tip "6-rapid" salta a Muse Spark 1.3 Contributor
     const f = empresa(name);
     const goTxt = cat === 'go'
       ? '<b style="color:' + COL.go + '">Go: sí</b>' + (ag ? ' · <span style="color:' + COL.go + '">★' + ag + '</span>' : '')
       : (cat === 'free'
         ? '<b style="color:' + COL.free + '">Zen Free: sí</b>' + (ag ? ' · <span style="color:' + COL.free + '">★' + ag + '</span>' : '')
         : (cat === 'cbx'
           ? '<b style="color:' + COL.cbx + '">Chatbox: sí</b>'
           : (cat === 'api'
             ? '<b style="color:' + COL.api + '">API: sí</b>'
             : 'Go: no')));
     const u = US.get(name + '|' + route);
     const TG = USTAG.get(name + '|' + route);
     // --- sub-AA 4 línies (17-09): AA + req/5h + req/dia + req/mes sota cada AA ---
     const unit = /msg\//.test(limit) ? 'msg' : 'req';
     const fmtInt = n => Math.round(n).toLocaleString('ca-ES');
     const fmtDia = n => (n >= 10 ? fmtInt(n) : n.toLocaleString('ca-ES', {maximumFractionDigits: 1}));
     let subAA = '';
     if (u === 0) subAA = '<div class="subaa">— ' + unit + '/5h · — ' + unit + '/dia · — ' + unit + '/mes</div>';
     else if (u == null) subAA = '<div class="subaa">s/d ' + unit + '/5h · s/d ' + unit + '/dia · s/d ' + unit + '/mes</div>';
     else {
       const dVal = u / 30;
       const mh = limit.match(/(≈?)\s*([\d.,]+)\s*req\/5h/);
       const mhMsg = limit.match(/(\d+)\s*-\s*(\d+)\s*msg\/5h/);
       let hFmt;
       if (mh) hFmt = (mh[1] || '') + mh[2] + '/5h';
       else if (mhMsg) hFmt = mhMsg[1] + '-' + mhMsg[2] + '/5h';
       else hFmt = '≈' + fmtDia(dVal * 5 / 24) + '/5h';
       const mBart = fmtInt(u) + ' ' + unit + '/mes · ' + TG;
       const mEx = (TG === 'OFI') ? mBart : '≈' + mBart;
       // Go: mes exacte (docs) · dia ≈ · 5h exacte del text; resta: tot ≈
       subAA = '<div class="subaa">' + hFmt.replace('/5h', ' ' + unit + '/5h') + ' · ≈' + fmtDia(dVal) + ' ' + unit + '/dia · ' + mEx + '</div>';
     }
     // --- doble barra 17-09, eix central 18-09: INTEL ◀ ancorada al CENTRE (dreta de la pista esquerra) · ÚS ▶ ancorat al CENTRE (esquerra de la pista dreta) ---
     // Cantonades QUADRADES (sense arrodoniment): les pistes s'ajunten al mig.
     const pctI = has ? Math.min(100, M.mean) : 0;
     const pctU = (u !== null && u !== 0 && u !== undefined) ? sqrtU(u) : 0;
     const tramAA = pctI ? '<div style="flex:1"></div><div style="width:' + Math.max(2.5,pctI).toFixed(1) + '%;background:' + color + ';border-radius:0"></div>'
                         : '<div style="flex:1"></div><div style="width:3%;background:' + color + ';opacity:.35;border-radius:0"></div>';
     const tramUS = pctU ? '<div style="width:' + Math.max(2.5,pctU).toFixed(1) + '%;background:var(--us);border-radius:0"></div><div style="flex:1"></div>'
                         : '<div style="width:3%;background:var(--us);opacity:.35;border-radius:0"></div><div style="flex:1"></div>';
     // --- 2a barra (només Go amb via free): tram d'ÚS free ancorat al CENTRE (esquerra, família usabilitat ▶) ---
     const extra = (cat === 'go') ? EXTRA_FREE[name] : null;
     let trams2 = '';
