         const d2 = u2 / 30;
         const tg2 = extra.cap ? 'CAP' : '1/4';
         subWEB = '<div class="subaa">WEB · ≈' + fmtDia(d2 * 5 / 24) + ' req/5h · ≈' + fmtDia(d2) + ' req/dia · ≈' + fmtInt(u2) + ' req/mes · ' + tg2 + '</div>';
       }
     }
     const goAbove = (cat === 'go') ? subAA.replace('class="subaa">', 'class="subaa">GO · ') : '';
     const below = (cat === 'go') ? subWEB : subAA;
