     const eff = effortTxt(name);
     row.title = name + ' — ' + f + ' — ' + route + (ag ? ' (★agent ' + ag + ')' : '') + ' — '
       + det4F
       + ' — ⚙️ Esforç: ' + eff + ' (mapa effort a dades_llm.js, docs oficials 17/18-09)'
       + ' — ús/mes: ' + (u == null ? 's/d' : (u === 0 ? 'sense accés' : (Math.round(u).toLocaleString('ca-ES') + ' · ' + TG + ' (' + USDET.get(name + '|' + route) + ')')))
       + (extra ? ' — FREE: ' + extra.via + ' (' + extra.nota + ')' : '')
