     row.innerHTML = `
       <div style="min-width:0">
         <div class="nom">${name}${capsVia(name, route) ? ' <span class="caps" title="Capacitats: 📝 text · 💻 codi · 🖼️ imatge · 🎵 àudio · 🎬 vídeo · 🔍 cerca web (nativa al canal o executada per l\'agent)">' + capsVia(name, route) + '</span>' : ''}</div>
