         ${PC[name] ? '<div class="via">✅ ' + PC[name][0] + '</div><div class="via">❌ ' + PC[name][1] + '</div>' : ''}
       </div>
       <div class="barra-zona doble">
           <div class="etiqueta" title="Mitjana 4F d'intel·ligència en escala AA (pes igual, cada font mapejada al rang AA del set): AA Index + Arena Elo + LiveBench + BenchLM agregat · ≈ si <4 fonts o AA provisional">${label}</div>
         ${goAbove ? '<div class="etiqueta-req">' + goAbove + '</div>' : '<div></div>'}
         <div>
           <div class="barra-fons">
