 }

 // ---------- CERCA type-to-jump ----------
 const cercaEl = document.getElementById('cerca');
 const cercaInfo = document.getElementById('cercaInfo');
 const selCaps = document.getElementById('selCaps');
 let cercaIdx = 0, cercaLlista = [];
 function normTxt(s){ return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }
 function cerca(){
   document.querySelectorAll('#rows .fila').forEach(r => r.classList.remove('cerca-match'));
   cercaLlista = []; cercaInfo.textContent = '';
   const q = normTxt(cercaEl.value.trim());
   if(!q) return;
   const files = [...document.querySelectorAll('#rows .fila')];
   const txt = r => normTxt((r.dataset.nom || '') + ' ' + (r.dataset.agent || ''));   // cerca nom O agent numerat (08-09)
   cercaLlista = files.filter(r => txt(r).startsWith(q));      // primer: comença per
   if(!cercaLlista.length) cercaLlista = files.filter(r => txt(r).includes(q)); // fallback: conté
   if(!cercaLlista.length){ cercaInfo.textContent = 'cap coincidència'; return; }
   cercaIdx = 0; saltaMatch();
 }
 function saltaMatch(){
   cercaLlista.forEach(r => r.classList.remove('cerca-match'));
   const el = cercaLlista[cercaIdx];
   if(!el) return;
   el.classList.add('cerca-match');
   el.scrollIntoView({behavior:'smooth', block:'center'});
   cercaInfo.textContent = (cercaIdx + 1) + '/' + cercaLlista.length + ' coincidències · Enter = següent · Esc = neteja';
 }
 cercaEl.addEventListener('input', () => { cercaIdx = 0; cerca(); });
 cercaEl.addEventListener('keydown', e => {
   if(e.key === 'Enter'){ e.preventDefault(); if(cercaLlista.length){ cercaIdx = (cercaIdx + 1) % cercaLlista.length; saltaMatch(); } }
   if(e.key === 'Escape'){ cercaEl.value = ''; cercaIdx = 0; cerca(); cercaEl.blur(); }
 });

 const sel = document.getElementById('selOrdena');
 sel.addEventListener('change', () => renderRows(sel.value));
 selCaps.addEventListener('change', () => renderRows(sel.value));
 selGo.addEventListener('change', () => renderRows(sel.value));
 selEffort.addEventListener('change', () => renderRows(sel.value));
 renderRows('intel');
 </script>
