     --bg:#2a2e36; --bg-accent:#2b303a; --surface-1:#313843; --surface-2:#3b4350;
     --border:#4a5462; --border-soft:#3d4552;
     --text-primary:#f7f5ef; --text-secondary:#cfccc2; --text-muted:#a5a29a;
     --text-accent:#fbbf24; --us:#cdb271;
     --radius:14px;
     --shadow:0 6px 22px rgba(0,0,0,.35);
     --shadow-hover:0 10px 28px rgba(0,0,0,.45);
   }
   *{box-sizing:border-box; margin:0; padding:0;}
   body{background:radial-gradient(1200px 500px at 20% -10%, #3b4350 0%, var(--bg) 55%) fixed, var(--bg);
        color:var(--text-primary);
        font:14px/1.5 "Segoe UI", Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
        padding:30px 3vw 60px; max-width:none; margin:0;}
   .sr-only{position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap;}
   h1{font-size:1.35rem; letter-spacing:.2px; margin-bottom:4px;
      background:linear-gradient(90deg,#fbbf24,#f59e0b 60%,#ef8354);
      -webkit-background-clip:text; background-clip:text; color:transparent;}
   .sub{font-size:12px; color:var(--text-secondary); margin-bottom:14px;}
   .notes{background:linear-gradient(180deg,var(--surface-1),var(--bg-accent));
          border:1px solid var(--border-soft); border-left:3px solid var(--text-accent) !important;
          border-radius:var(--radius); padding:14px 16px; margin-bottom:14px;
          box-shadow:var(--shadow); font-size:12px; color:var(--text-secondary);}
   .notes ul{margin:6px 0 0 18px;}
   .notes li{margin:3px 0;}
   .legend{display:flex; flex-wrap:wrap; gap:8px; font-size:11.5px; color:var(--text-secondary); margin-bottom:8px;}
   .legend span{display:inline-flex; align-items:center; gap:6px; background:var(--surface-1);
                border:1px solid var(--border-soft); border-radius:999px; padding:3px 11px;}
   .sw{width:9px; height:9px; border-radius:50%; display:inline-block; box-shadow:0 0 6px currentColor;}
   .axis{font-size:11px; color:var(--text-muted); margin-bottom:12px;}
   #rows{display:flex; flex-direction:column; gap:2px;}
   /* CENTRES ALINEATS (18-09): cada .fila era una graella independent i els triples
      nowrap (GO·req/5h·dia·mes) eixamplaven la columna de barres diferent a cada fila.
      Amb minmax(0,...) + min-width:0 el contingut ja no eixampla: la columna de barres
      té la mateixa amplada a totes les files i els centres queden en vertical. */
   .fila{display:grid; grid-template-columns:220px minmax(0,1.6fr) minmax(0,1fr); column-gap:18px; align-items:center;
         background:transparent; border:none; border-bottom:1px solid var(--border-soft);
         border-radius:0; padding:3px 8px; box-shadow:none;
         transition:background .1s ease;}
   .fila > div{min-width:0;}
   .fila:hover{transform:none; box-shadow:none; border-color:var(--border-soft); background:rgba(255,255,255,.03);}
   .fila[data-cat="go"]{--accent:#7ba7d4;}
   .fila[data-cat="web"]{--accent:#6fbf9a;}
   .fila[data-cat="cli"]{--accent:#3fc1c9;}
   .fila[data-cat="ide"]{--accent:#a89fdf;}
   .fila[data-cat="free"]{--accent:#d693b3;}
   .fila[data-cat="no"]{--accent:#cf8578;}
   .fila[data-cat="cbx"]{--accent:#a3e635;}
   .fila[data-cat="api"]{--accent:#fb923c;}
   .fila.cerca-match{outline:2px solid var(--text-accent); background:var(--surface-2);}
   .nom{font-size:12.5px; font-weight:600; color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
        display:flex; align-items:center; gap:5px;}
   .empresa{font-size:11px; color:var(--text-secondary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-top:2px;}
   .caps{font-size:10px; opacity:.95; margin-left:3px; letter-spacing:1px;}
   .via{font-size:11px; color:var(--text-secondary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-top:2px;}
   .effort{font-size:11px; color:var(--text-secondary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-top:2px;}
   .effort b{color:var(--text-primary); font-weight:600;}
   .barra-zona{display:flex; align-items:center; gap:8px;}
   .barra-zona.doble{display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:4px 0; align-items:start; min-width:0; position:relative;}
   .barra-zona.doble > div{min-width:0;}
   /* RATLLA BLANCA al centre (18-09, petició operador): marca el 0 a la juntura de les
      dues pistes — intel·ligència ◀ a l'esquerra, usabilitat ▶ a la dreta. Comença sota
      les etiquetes per no creuar text. */
   .barra-zona.doble::before{content:""; position:absolute; left:50%; top:22px; bottom:0; width:2px;
         background:#fff; opacity:.9; pointer-events:none; transform:translateX(-50%);}
   /* EIX CENTRAL (18-09, petició operador): pistes AJUNTADES al mig, sense espai ni
      arrodoniment — intel·ligència ◀ des del centre cap a l'esquerra, usabilitat ▶
      des del centre cap a la dreta. Sense vora interior perquè es toquin del tot. */
   .barra-zona.doble .barra-fons{background:#232831;}
   .barra-zona.doble > div:nth-child(3) .barra-fons{border-right:none; border-radius:0;}
   .barra-zona.doble > div:nth-child(4) .barra-fons{border-left:none; border-radius:0;}
   .colBar{min-width:0;}
   .etiqueta{font-size:11.5px; font-weight:600; color:var(--text-secondary); margin-bottom:3px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
   .etiqueta-req{margin-top:3px; min-width:0;}
   /* El triple GO/WEB sota les barres podia ser molt llarg i forçava la columna (nowrap):
      ara pot partir en 2 línies perquè no mogui el centre. */
   .etiqueta-req .subaa{font-size:10px; font-weight:400; color:var(--text-muted); white-space:normal; overflow-wrap:anywhere; line-height:1.45;}
   .barra-fons{flex:1; background:#232831; border:1px solid var(--border-soft); border-radius:0; height:10px; position:relative; overflow:hidden;}
   .valor{font-size:11.5px; font-weight:600; color:var(--text-secondary); min-width:96px; text-align:right; line-height:1.4;}
   .valor .subaa{font-size:10px; font-weight:400; color:var(--text-muted); white-space:nowrap; line-height:1.45;}
   .limit{font-size:11px; color:var(--text-muted); line-height:1.45;}
   .dim{font-size:10px; margin-top:3px; color:var(--text-secondary); background:rgba(255,255,255,.04);
        border-radius:8px; padding:2px 8px; display:inline-block;}
   select, input[type="search"]{background:var(--surface-2); color:var(--text-primary);
        border:1px solid var(--border); border-radius:999px; padding:7px 12px; font-size:11.5px; outline:none;}
   select:focus, input[type="search"]:focus{border-color:var(--text-accent); box-shadow:0 0 0 2px rgba(245,158,11,.25);}
   footer{margin-top:20px; font-size:11px; color:var(--text-muted); line-height:1.6;
          border:1px solid var(--border-soft); background:var(--bg-accent);
          border-radius:var(--radius); padding:14px 16px;}
   @media (max-width:900px){
     .fila{grid-template-columns:1fr; row-gap:8px;}
     body{padding:20px 14px 50px;}
   }
 </style>
